const isAddedContentDiffLine = (line: string): boolean =>
  (line.startsWith('+') &&
    !line.startsWith('+++') &&
    line.slice(1).trim().length > 0) ||
  /^Binary files \/dev\/null and b\/.+ differ$/.test(line);

export const countAddedContentDiffLines = (diff: string): number =>
  diff.split('\n').filter(isAddedContentDiffLine).length;
